definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '20'))
    timeout(time: 30, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  triggers {
    // Weekly, Sunday ~05:00 — after docker-dedupe (~04:00).
    cron('H 5 * * 0')
  }

  stages {
    stage('Registry GC') {
      steps {
        sh '''
          set -e
          echo "== BEFORE ==" ; docker exec registry du -sh /var/lib/registry 2>/dev/null || true
          # CNCF registry GC: removes blobs no longer referenced by any
          # manifest. --delete-untagged also drops untagged manifests.
          # Best run with no concurrent pushes; we restart after to be safe.
          docker exec registry registry garbage-collect --delete-untagged \
            /etc/docker/registry/config.yml
          echo "== AFTER ==" ; docker exec registry du -sh /var/lib/registry 2>/dev/null || true
          docker restart registry >/dev/null
          echo "registry restarted; GC complete"
        '''
      }
    }
  }

  post {
    always { cleanWs() }
  }
}
